import {request} from './api.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function showPrivateReview(app,pid,onDone){
 let data=await request('/papers/'+encodeURIComponent(pid)+'/review'),checked=new Map(),saving=false;
 function draw(){
  const p=data.paper;
  app.innerHTML=`<a class="as-btn" href="#exam/upload">返回我的试卷</a><h1>校对原题 · ${esc(p.title)}</h1><p>对照原图核对题干和选项。没有可靠答案的题目会保存作答并显示未评分。</p>${p.excluded_question_count?`<p role="alert">原卷有 ${p.excluded_question_count} 道题存在结构异常，尚未纳入；请结合原始文件检查。本次不代表完整原卷。</p>`:''}${data.questions.map(q=>`<section class="as-panel" data-review-question="${esc(q.question_id)}"><h2>第 ${esc(q.source_number)} 题</h2>${[...q.shared_assets,...q.assets].map(a=>`<img class="as-image" src="/api/v4/assets/${encodeURIComponent(a)}" alt="第 ${esc(q.source_number)} 题原图及公式">`).join('')}<form class="as-form" data-edit="${esc(q.question_id)}"><label>题干<textarea name="stem" required ${p.published?'readonly':''}>${esc(q.stem)}</textarea></label>${q.options.map(o=>`<label>选项 ${esc(o.label)}<textarea name="${esc(o.label)}" required ${p.published?'readonly':''}>${esc(o.text)}</textarea></label>`).join('')}${!p.published?'<button class="as-btn" type="submit">保存修订</button>':''}</form>${!p.published?`<label><input type="checkbox" data-reviewed="${esc(q.question_id)}" ${checked.get(q.question_id)===q.version_id?'checked':''}>已对照原图核对这一题</label>`:'<p>已确认当前版本</p>'}</section>`).join('')}<p role="status" data-review-status></p><div class="as-actions">${p.published?'<button class="as-btn primary" data-done>开始练习或模考</button>':'<button class="as-btn primary" data-confirm>确认全部题目</button>'}</div>`;
  app.querySelector('[data-done]')?.addEventListener('click',()=>onDone(pid));
  app.querySelectorAll('[data-reviewed]').forEach(b=>b.onchange=()=>{const q=data.questions.find(q=>q.question_id===b.dataset.reviewed);if(b.checked)checked.set(q.question_id,q.version_id);else checked.delete(q.question_id);});
  app.querySelectorAll('[data-edit]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();if(saving)return;saving=true;const q=data.questions.find(q=>q.question_id===f.dataset.edit),fields=new FormData(f);try{data=await request('/papers/'+pid+'/review/'+q.question_id,{method:'PATCH',body:{expected_revision:data.revision,expected_version:q.version_id,stem:fields.get('stem'),options:q.options.map(o=>({label:o.label,text:fields.get(o.label)}))}});checked.delete(q.question_id);draw();}catch(error){app.querySelector('[data-review-status]').textContent=error.message;}finally{saving=false;}});
  app.querySelector('[data-confirm]')?.addEventListener('click',async()=>{if(saving)return;if(checked.size!==data.questions.length){app.querySelector('[data-review-status]').textContent='请逐题核对并勾选确认。';return;}saving=true;try{await request('/papers/'+pid+'/confirm',{method:'POST',body:{expected_revision:data.revision,reviewed_versions:Object.fromEntries(checked)}});data=await request('/papers/'+pid+'/review');draw();}catch(error){app.querySelector('[data-review-status]').textContent=error.message;}finally{saving=false;}});
 }
 draw();
}
